package frc.robot.application.auto.routines;

import edu.wpi.first.math.geometry.Pose2d;
import edu.wpi.first.math.geometry.Rotation2d;
import frc.robot.application.auto.ActionList;
import frc.robot.application.auto.Waylist;
import frc.robot.application.superstructure.SS.Flag;

/** Generated by the APF Auto Planner. */
public final class PlannedAuto {
    private PlannedAuto() {}

    public static ActionList build() {
        // The planner's first pose is the odometry reset pose.
        ActionList auto = new ActionList("PLANNED_AUTO",
                new Pose2d(4.530, 7.491, Rotation2d.fromDegrees(0.0)),
                ActionList.PathingStyle.CONTINUOUS).startActions();
        auto.waitFor(5.0); // IDLE; ends on time

        auto.waitFor(1.0); // IDLE; ends on time

        Waylist path0 = new Waylist(
                new Pose2d(4.530, 7.491, Rotation2d.fromDegrees(0.0)), 0.1)
                .append(new Pose2d(8.633, 7.328, Rotation2d.fromDegrees(-84.0)), 0.1);
        auto.driveToPose(path0, 2.5, 2.5, 0.2); // IDLE

        auto.waitFor(2.0); // IDLE; ends on time

        auto.waitFor(1.0); // IDLE; ends on time

        Waylist path1 = new Waylist(
                new Pose2d(8.633, 7.328, Rotation2d.fromDegrees(-84.0)), 0.1)
                .append(new Pose2d(8.957, 4.187, Rotation2d.fromDegrees(0.0)), 0.1);
        auto.driveToPose(path1, 2.5, 2.5, 0.2); // IDLE

        return auto;
    }
}
